'use strict';

const HEAD1 = 0x57;
const HEAD2 = 0xab;
const ADDR = 0x00;

const CMD_GET_INFO = 0x01;
const CMD_SEND_KB_GENERAL_DATA = 0x02;
const CMD_SEND_MS_ABS_DATA = 0x04;
const CMD_SEND_MS_REL_DATA = 0x05;

function buildCmdPacket(command, data) {
  const payload = Array.isArray(data) ? data : Array.from(data || []);
  const len = payload.length;
  let sum = HEAD1 + HEAD2 + ADDR + command + len;
  for (const byte of payload) {
    sum += byte;
  }
  sum &= 0xff;
  return Buffer.from([HEAD1, HEAD2, ADDR, command, len, ...payload, sum]);
}

function toUnsignedByte(value) {
  const rounded = Math.round(value);
  if (rounded < 0) return 256 + rounded;
  return rounded;
}

function buildRelativeMousePayload(buttons, dx, dy, wheel = 0) {
  const boundedX = Math.max(-127, Math.min(127, Math.round(dx)));
  const boundedY = Math.max(-127, Math.min(127, Math.round(dy)));
  const boundedWheel = Math.max(-127, Math.min(127, Math.round(wheel)));

  return [
    0x01,
    buttons,
    toUnsignedByte(boundedX),
    toUnsignedByte(boundedY),
    toUnsignedByte(boundedWheel)
  ];
}

function buildAbsoluteMousePayload(buttons, x, y, screenWidth, screenHeight, wheel = 0) {
  const width = Math.max(1, Math.round(screenWidth || 1));
  const height = Math.max(1, Math.round(screenHeight || 1));
  const boundedX = Math.max(0, Math.min(width, Math.round(x)));
  const boundedY = Math.max(0, Math.min(height, Math.round(y)));
  const hidX = Math.max(0, Math.min(4096, Math.round((boundedX * 4096) / width)));
  const hidY = Math.max(0, Math.min(4096, Math.round((boundedY * 4096) / height)));
  const boundedWheel = Math.max(-127, Math.min(127, Math.round(wheel)));

  return [
    0x02,
    buttons,
    hidX & 0xff,
    (hidX >> 8) & 0xff,
    hidY & 0xff,
    (hidY >> 8) & 0xff,
    toUnsignedByte(boundedWheel)
  ];
}

function buildMouseClickPayload(buttons) {
  return buildRelativeMousePayload(buttons, 0, 0, 0);
}

function buildKeyboardPacketData(modifierMask, keyCodes) {
  const keys = Array.isArray(keyCodes) ? keyCodes.slice(0, 6) : [];
  while (keys.length < 6) {
    keys.push(0x00);
  }
  return [modifierMask & 0xff, 0x00, ...keys];
}

module.exports = {
  CMD_GET_INFO,
  CMD_SEND_KB_GENERAL_DATA,
  CMD_SEND_MS_ABS_DATA,
  CMD_SEND_MS_REL_DATA,
  buildCmdPacket,
  buildAbsoluteMousePayload,
  buildRelativeMousePayload,
  buildMouseClickPayload,
  buildKeyboardPacketData
};
